package com.mavric.health.documents.application;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import com.mavric.health.identity.*;
import com.mavric.health.tenancy.TenantRef;
import com.mavric.health.shared.*;
import com.mavric.health.documents.domain.Requests.*;
import com.mavric.health.persistence.sqlserver.*;
import com.mavric.health.persistence.sqlserver.SqlServerDocumentStoreTest.Fixture;
import com.mavric.health.audit.TraceContext;
import static com.mavric.health.persistence.sqlserver.SqlServerDocumentStoreTest.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
/** Real service/store with modeled transactions; no live HTTP/JDBC/signature or link evidence. */
class DocumentServiceSqlServerTest {
 final Fixture f=new Fixture();final Access access=mock(Access.class);final Sql sql=mock(Sql.class);final DocumentService service=new DocumentService(f.store,access);
 DocumentServiceSqlServerTest(){actor("PRO");when(access.tenantId()).thenReturn(TENANT);when(access.userId()).thenReturn(ACTOR);}
 void actor(String role){f.actor(role);doReturn(f.actor).when(access).actor();TraceContext.REQUEST.set(f.request);}
 @AfterEach void clean(){TraceContext.REQUEST.remove();SecurityContextHolder.clearContext();TransactionSynchronizationManager.clear();}
 @Test void readRolesAreTenantWideWithNoBranchLinkWriteOrStatusGate(){for(String role:List.of("PRO","ASI","AUD")){actor(role);f.request.setAttribute("health.tenant",new TenantRef(TENANT,"Synthetic","clinic","CLINIC","HUMAN","SUSPENDED",List.of()));assertEquals(List.of(),service.list(PATIENT));assertEquals(16,((Map<?,?>)service.get(DOCUMENT)).size());}assertEquals(List.of(SqlServerProcedure.DOCUMENTS_LIST,SqlServerProcedure.DOCUMENT_GET,SqlServerProcedure.DOCUMENTS_LIST,SqlServerProcedure.DOCUMENT_GET,SqlServerProcedure.DOCUMENTS_LIST,SqlServerProcedure.DOCUMENT_GET),f.calls);verify(access,times(6)).roles("PRO","ASI","AUD");verify(access,never()).branch(anyString());verify(access,never()).link(anyString(),anyString());verify(access,never()).write(anyString(),any(String[].class));verifyNoInteractions(sql);}
 @Test void listPatientPresenceAndAuditAreDelegatedToSingleSpNoPrelookup(){doThrow(new RuntimeException(new java.sql.SQLException("private patient canary",null,51002))).when(f.executor).execute(eq(SqlServerProcedure.DOCUMENTS_LIST),any(),eq(PATIENT));var error=assertThrows(ApiException.class,()->service.list(PATIENT));assertEquals(404,error.status);assertNull(error.getCause());verify(f.executor).execute(eq(SqlServerProcedure.DOCUMENTS_LIST),any(),eq(PATIENT));verifyNoMoreInteractions(f.executor);verifyNoInteractions(sql);}
 @Test void createOneSpDtoUnicodeNullableNoGetOrJavaAudit(){var row=(Map<?,?>)service.create(input());assertEquals(16,row.size());assertEquals("DRAFT",row.get("status"));assertEquals(input().content(),row.get("content"));assertNull(row.get("contentHash"));assertEquals(List.of(SqlServerProcedure.DOCUMENT_CREATE),f.calls);verify(access).write("CORE","PRO");verify(access,never()).branch(anyString());verify(access,never()).link(anyString(),anyString());assertEquals(List.of("begin:0","sp:DOCUMENT_CREATE","commit"),f.manager.events);verifyNoInteractions(sql);}
 @Test void changeKeepsAuditedGetBeforeValidationAndSingleMutationNoTrailingGet(){var result=(Map<?,?>)service.change(DOCUMENT,new Change(1,"SAVE","Synthetic saved"));assertEquals("Synthetic saved",result.get("content"));assertEquals(2,result.get("revision"));assertEquals(List.of(SqlServerProcedure.DOCUMENT_GET,SqlServerProcedure.DOCUMENT_CHANGE),f.calls);var order=inOrder(access,f.executor);order.verify(access).write("CORE","PRO");order.verify(access).roles("PRO","ASI","AUD");order.verify(f.executor).execute(eq(SqlServerProcedure.DOCUMENT_GET),any(),eq(DOCUMENT));order.verify(f.executor).execute(eq(SqlServerProcedure.DOCUMENT_CHANGE),any(),eq(DOCUMENT),eq(1),eq("SAVE"),eq("Synthetic saved"));assertEquals(1,Collections.frequency(f.manager.events,"begin:0"));assertEquals(1,Collections.frequency(f.manager.events,"commit"));verifyNoInteractions(sql);}
 @Test void blankSaveKeepsLegacyMessageAfterPriorReadAndRollsBackReadAuditModel(){for(String content:Arrays.asList(null,""," ")){var e=assertThrows(ApiException.class,()->service.change(DOCUMENT,new Change(1,"SAVE",content)));assertEquals(400,e.status);assertEquals("Escribe el contenido del borrador.",e.getMessage());assertEquals(SqlServerProcedure.DOCUMENT_GET,f.calls.getLast());assertEquals("rollback",f.manager.events.getLast());}assertEquals(3,f.calls.size());verifyNoInteractions(sql);}
 @Test void signPublishWithdrawConsumeSpSignatureAndFlagsWithoutRecomputingOrLinkQueries(){for(String operation:List.of("SIGN","PUBLISH","WITHDRAW")){f.current=operation.equals("SIGN")?document():signed();var row=(Map<?,?>)service.change(DOCUMENT,new Change(1,operation,null));assertEquals("SIGNED",row.get("status"));assertNotNull(row.get("contentHash"));if(operation.equals("PUBLISH"))assertEquals(true,row.get("published"));if(operation.equals("WITHDRAW"))assertEquals(true,row.get("withdrawn"));assertEquals(SqlServerProcedure.DOCUMENT_CHANGE,f.calls.getLast());assertNull(f.args.getLast().get(3));}assertEquals(6,f.calls.size());verify(access,never()).module("PORTAL");verify(access,never()).link(anyString(),anyString());verifyNoInteractions(sql);}
 @Test void signedSavePublishWithoutLinkAndRevisionConflictsAreSpErrorsNotJavaSimulation(){f.current=signed();doThrow(new RuntimeException(new java.sql.SQLException("private immutable signature canary",null,51003))).when(f.executor).execute(eq(SqlServerProcedure.DOCUMENT_CHANGE),any(),any(Object[].class));for(Change change:List.of(new Change(1,"SAVE","Synthetic"),new Change(1,"PUBLISH",null),new Change(7,"SIGN",null))){var e=assertThrows(ApiException.class,()->service.change(DOCUMENT,change));assertEquals(409,e.status);assertEquals("CONFLICT",e.code);assertNull(e.getCause());assertFalse(e.toString().contains("canary"));}assertEquals(3,f.calls.size());verify(f.executor,times(3)).execute(eq(SqlServerProcedure.DOCUMENT_CHANGE),any(),any(Object[].class));verifyNoInteractions(sql);}
 @Test void writeRolesAndPublicAuthorityHeadersNeverGrantPermission(){for(String role:List.of("ASI","AUD","ADM","REC","PAC","RES","SAD","SOP")){actor(role);f.request.addHeader("X-Roles","PRO");assertEquals(403,assertThrows(ApiException.class,()->service.create(input())).status);assertEquals(403,assertThrows(ApiException.class,()->service.change(DOCUMENT,new Change(1,"SIGN",null))).status);}verifyNoInteractions(f.executor,sql);}
 @Test void requestActorHostAndMissingAuthenticationAreCheckedBeforeAllEffects(){TraceContext.REQUEST.remove();assertEquals(500,assertThrows(ApiException.class,()->service.list(PATIENT)).status);actor("PRO");doThrow(new ApiException(401,"UNAUTHENTICATED","Safe")).when(access).actor();assertEquals(401,assertThrows(ApiException.class,()->service.get(DOCUMENT)).status);actor("PRO");f.request.setAttribute("health.actor","forged");assertEquals(403,assertThrows(ApiException.class,()->service.create(input())).status);actor("PRO");f.request.setAttribute("health.tenant","bad");assertEquals(500,assertThrows(ApiException.class,()->service.change(DOCUMENT,new Change(1,"SIGN",null))).status);actor("PRO");f.request.setAttribute("health.tenant",new TenantRef(OTHER,"Foreign","foreign","CLINIC","HUMAN","ACTIVE",List.of("CORE")));assertEquals(403,assertThrows(ApiException.class,()->service.get(DOCUMENT)).status);actor("PRO");doReturn(new Actor(ACTOR,"Synthetic","synthetic@example.test",null,List.of("SAD"),"a".repeat(64))).when(access).actor();f.request.removeAttribute("health.tenant");assertEquals(403,assertThrows(ApiException.class,()->service.list(PATIENT)).status);verify(access,never()).write(anyString(),any(String[].class));verifyNoInteractions(f.executor,sql);}
 @Test void writeAndPriorReadDenialsStopBeforeDocumentMutation(){doThrow(new ApiException(403,"SUSPENDED","Safe")).when(access).write("CORE","PRO");assertEquals(403,assertThrows(ApiException.class,()->service.create(input())).status);assertEquals(403,assertThrows(ApiException.class,()->service.change(DOCUMENT,new Change(1,"SIGN",null))).status);doNothing().when(access).write("CORE","PRO");doThrow(ApiException.forbidden()).when(access).roles("PRO","ASI","AUD");assertEquals(403,assertThrows(ApiException.class,()->service.change(DOCUMENT,new Change(1,"SIGN",null))).status);verifyNoInteractions(f.executor,sql);}
 @Test void nullAndInvalidDtoInputsNeverWriteAndPriorGetRemainsForChange(){assertEquals(400,assertThrows(ApiException.class,()->service.create(null)).status);assertEquals(400,assertThrows(ApiException.class,()->service.get("bad")).status);assertEquals(400,assertThrows(ApiException.class,()->service.list("bad")).status);verifyNoInteractions(f.executor);for(Change change:Arrays.asList(null,new Change(0,"SIGN",null),new Change(1,"bad",null))){assertEquals(400,assertThrows(ApiException.class,()->service.change(DOCUMENT,change)).status);}assertEquals(Collections.nCopies(3,SqlServerProcedure.DOCUMENT_GET),f.calls);}
 @Test void getAndChangeSpErrorCommitAndOuterRollbackNeverFallback(){doThrow(new RuntimeException(new java.sql.SQLException("private driver canary",null,51002))).when(f.executor).execute(eq(SqlServerProcedure.DOCUMENT_GET),any(),eq(DOCUMENT));assertEquals(404,assertThrows(ApiException.class,()->service.change(DOCUMENT,new Change(1,"SAVE",""))).status);verify(f.executor,never()).execute(eq(SqlServerProcedure.DOCUMENT_CHANGE),any(),any(Object[].class));reset(f.executor);doAnswer(inv->{boolean get=inv.getArgument(0)==SqlServerProcedure.DOCUMENT_GET;var row=document();if(!get)row.put("revision",2);return result(List.of(row));}).when(f.executor).execute(any(),any(),any(Object[].class));f.manager.failCommit=true;var error=assertThrows(ApiException.class,()->service.change(DOCUMENT,new Change(1,"WITHDRAW",null)));assertEquals(500,error.status);assertNull(error.getCause());assertThrows(RuntimeException.class,()->f.manager.outer(()->{service.change(DOCUMENT,new Change(1,"WITHDRAW",null));throw new RuntimeException("cancel");}));assertEquals("rollback",f.manager.events.getLast());assertSame(f.actor,f.request.getAttribute("health.actor"));assertNull(SecurityContextHolder.getContext().getAuthentication());verifyNoInteractions(sql);}
 @Test void malformedMutationRowsRollbackAndNeverExposePrivateColumns(){var row=document();row.put("tenantId",OTHER);row.put("passwordHash","canary");f.results.add(result(List.of(document())));f.results.add(result(List.of(row)));var error=assertThrows(ApiException.class,()->service.change(DOCUMENT,new Change(1,"SIGN",null)));assertEquals(500,error.status);assertEquals("DATABASE_ERROR",error.code);assertNull(error.getCause());assertFalse(error.toString().contains("canary"));assertEquals("rollback",f.manager.events.getLast());}
 @Test void minimalSpringSelectsLegacyConstructorWithoutDatasourceOrSqlStore(){when(sql.one(anyString(),any(Object[].class))).thenAnswer(inv->document());when(sql.rows(anyString(),any(Object[].class))).thenReturn(List.of());when(sql.json(any())).thenReturn("{}");try(var context=new AnnotationConfigApplicationContext()){context.registerBean(Sql.class,()->sql);context.registerBean(Access.class,()->access);context.registerBean(DocumentService.class);context.refresh();var legacy=context.getBean(DocumentService.class);assertEquals(List.of(),legacy.list(PATIENT));assertEquals(16,((Map<?,?>)legacy.get(DOCUMENT)).size());verify(sql).call(eq("sp_audit"),eq(TENANT),eq(ACTOR),eq("DOCUMENT_LIST_READ"),eq(PATIENT),eq("{}"));verify(sql).call(eq("sp_audit"),eq(TENANT),eq(ACTOR),eq("DOCUMENT_READ"),eq(DOCUMENT),eq("{}"));assertEquals(0,context.getBeanNamesForType(SqlServerDocumentStore.class).length);assertEquals(0,context.getBeanNamesForType(javax.sql.DataSource.class).length);}verifyNoInteractions(f.executor);}
}
